//! Actions-only real original Common -> Hosted sync -> atomic IM SQL/history.
//! No device, original SDK loading or real Provider service is used.
use super::*;
use n::im_sync_policy::NativeImSyncConfig;
#[path="im_info_runtime_sync_account_tests.rs"]
mod info;
fn config(root:&str,port:u16,timeout:u64)->AccountConfig{let mut c=super::config(root,port,timeout);c.profile.im_sync=Some(NativeImSyncConfig{receive:true});c}
fn status(base:i64,target:i64,time:i64)->Vec<u8>{let mut w=Writer::new();w.boolean(true).unwrap();w.u32(1).unwrap();w.bytes(b"1_2").unwrap();let b=base.to_string();let t=target.to_string();w.properties(&[RpcProperty{key:n::im_status::PEER_READ,value:b.as_bytes()},RpcProperty{key:n::im_status::LATEST,value:t.as_bytes()}]).unwrap();w.i64(time).unwrap();w.bytes(b"").unwrap();w.finish().expose_to_transport().to_vec()}
fn received(indices:&[i64],unknown:bool)->Vec<u8>{let mut w=Writer::new();w.boolean(true).unwrap();w.u32(indices.len()as u32).unwrap();for(index,i)in indices.iter().zip(0..){w.i64(*index).unwrap();w.i64(1234567890123).unwrap();w.bytes(b"fixture-private-uid").unwrap();w.bytes(if unknown&&i==1{b"Info.Unknown"}else{b"Text"}).unwrap();w.bytes(br#"{"text":"original IM text","userData":"private-not-public"}"#).unwrap();w.properties(&[RpcProperty{key:b"../never-written",value:b"attachment-bytes"}]).unwrap();w.properties(&[]).unwrap();}w.bytes(b"").unwrap();w.finish().expose_to_transport().to_vec()}
async fn swap(peer:&mut CommonPeer,packet:&[u8]){let request=decode_request(&packet[1..]).unwrap();assert_eq!(request.method,n::rpc_batch::SWAP_CALLS_METHOD.as_bytes());let mut r=Reader::versioned(request.arguments).unwrap();assert_eq!(r.bytes().unwrap(),b"fixture-user");assert_eq!(r.bytes().unwrap(),b"fixture-original-selector");let p=n::rpc_batch::read_payload(&mut r).unwrap();assert!(p.requests.is_empty(),"no extra hosting/business write");peer.send(&[reply(request.call_id,&n::runtime_backend::tests::swap_result(None,true,p.fields))]).await;}
async fn group(peer:&mut CommonPeer,method:&str)->Vec<u8>{loop{let p=peer.next().await.unwrap();assert_eq!(p[0],0,"no unconsumed early IM ACK");let r=decode_request(&p[1..]).unwrap();if r.method==n::rpc_batch::SWAP_CALLS_METHOD.as_bytes(){swap(peer,&p).await;continue;}assert_eq!(r.method,method.as_bytes());assert_eq!(r.metadata.len(),2);assert_eq!(r.metadata.iter().find(|p|p.key==b"id").unwrap().value,b"#Group");assert_eq!(r.metadata.iter().find(|p|p.key==b"token").unwrap().value,b"fixture-auth");return p;}}
fn receive_span(packet:&[u8])->(i32,i64,u32){let request=decode_request(&packet[1..]).unwrap();let mut r=Reader::versioned(request.arguments).unwrap();assert_eq!(r.bytes().unwrap(),b"P2P/1_2");let start=r.i64().unwrap();let count=r.u32().unwrap();assert!((1..=10).contains(&count));r.finish().unwrap();(request.call_id,start,count)}
fn cursor(db:&crate::platform::db::Database,line:&str)->(i64,i64,i64){db.with_conn(|c|c.query_row("SELECT baseline,consumed,target FROM app_voice_im_receive_cursors WHERE line_id=?1 AND box_id=?2",rusqlite::params![line,b"P2P/1_2".as_slice()],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).map_err(|_|"fixture")).unwrap()}
async fn login_host(peer:&mut CommonPeer){let p=peer.next().await.unwrap();let login=decode_request(&p[1..]).unwrap();peer.send(&[reply(login.call_id,&login_result())]).await;let(_,flag)=hosting_call(peer).await;assert_eq!(flag,b"4");}
async fn refresh(peer:&mut CommonPeer,base:i64,target:i64,time:i64){let packet=group(peer,n::im_status::REFRESH_METHOD).await;let request=decode_request(&packet[1..]).unwrap();let mut r=Reader::versioned(request.arguments).unwrap();assert_eq!(r.bytes().unwrap(),b"fixture-user");peer.send(&[reply(request.call_id,&status(base,target,time))]).await;}
#[tokio::test]
async fn im_sync_account_three_original_bounded_reads_commit_before_matching_notice_ack_and_cleanup(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(config(&cert.root,port,3000),100).await.unwrap().account;let line=account.line_id.clone();let observed=temp.database.clone();let server_line=line.clone();let(done,received_done)=tokio::sync::oneshot::channel();
    let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;login_host(&mut peer).await;refresh(&mut peer,0,25,1).await;
        for(start,count_expected)in[(1,10),(11,10),(21,5)]{let packet=group(&mut peer,n::im_data::RECV_METHOD).await;let(id,actual,count)=receive_span(&packet);assert_eq!((actual,count),(start,count_expected));if start>1{assert_eq!(cursor(&observed,&server_line).1,start-1);}let indices=(start..start+i64::from(count)).collect::<Vec<_>>();peer.send(&[reply(id,&received(&indices,false))]).await;}
        // Original server notice is the causal barrier after the final read;
        // it can become positive only after actual matching SQL consumption.
        peer.send(&[hint(91,99,25)]).await;next_reply(&mut peer,91,true).await;assert_eq!(count(&observed),25);assert_eq!(cursor(&observed,&server_line),(0,25,25));done.send(()).unwrap();finish_account(&mut peer).await;
    }).await});
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(received_done).await.unwrap();assert_eq!(manager.im_messages(&line,128).unwrap().len(),25);assert!(manager.messages(&line,16).unwrap().is_empty());assert!(temp.database.get_call_history_for_line(&line,16,0).unwrap().is_empty());let events=temp.database.get_recent_app_events(Some(&line),128).unwrap();assert_eq!(events.iter().filter(|e|e.event_type=="im.received").count(),25);assert!(events.iter().all(|e|!e.payload_json.contains("private-not-public")));assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();assert!(!temp.database.with_conn(|c|n::account_runs::ownership_pending(c,&line)).unwrap());assert_eq!(cursor(&temp.database,&line),(0,25,25));
}).await;}
#[tokio::test]
async fn im_sync_account_out_of_order_online_waits_for_current_refresh_and_missing_records_without_extending_holder(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(config(&cert.root,port,3000),100).await.unwrap().account;let line=account.line_id.clone();let observed=temp.database.clone();let server_line=line.clone();let(done,finished)=tokio::sync::oneshot::channel();
    let(admitted,observed_admission)=tokio::sync::oneshot::channel();
    let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;login_host(&mut peer).await;let packet=group(&mut peer,n::im_status::REFRESH_METHOD).await;let id=decode_request(&packet[1..]).unwrap().call_id;peer.send(&[message(91,3,true),hint(92,99,3)]).await;observed_admission.await.unwrap();assert_eq!(count(&observed),0);peer.send(&[reply(id,&status(0,2,1))]).await;
        let packet=group(&mut peer,n::im_data::RECV_METHOD).await;let(id,start,count)=receive_span(&packet);assert_eq!((start,count),(1,3));assert_eq!(super::count(&observed),0);peer.send(&[reply(id,&received(&[1,2],false))]).await;next_reply(&mut peer,91,true).await;next_reply(&mut peer,92,true).await;assert_eq!(cursor(&observed,&server_line),(0,3,3));assert_eq!(super::count(&observed),3);done.send(()).unwrap();finish_account(&mut peer).await;
    }).await});
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(async{while manager.im_original_queue_admissions(&line).unwrap()<1{tokio::time::sleep(Duration::from_millis(5)).await;}}).await;admitted.send(()).unwrap();bounded(finished).await.unwrap();let rows=manager.im_messages(&line,16).unwrap();assert_eq!(rows.iter().map(|r|r.message_index.as_str()).collect::<Vec<_>>(),["3","2","1"]);assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();
}).await;}
#[tokio::test]
async fn im_sync_account_empty_gap_advances_only_cursor_and_notifies_missing_body_negative(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(config(&cert.root,port,100),100).await.unwrap().account;let line=account.line_id.clone();let observed=temp.database.clone();let server_line=line.clone();let(done,finished)=tokio::sync::oneshot::channel();
    let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;login_host(&mut peer).await;refresh(&mut peer,0,2,1).await;let packet=group(&mut peer,n::im_data::RECV_METHOD).await;let(id,start,count)=receive_span(&packet);assert_eq!((start,count),(1,2));peer.send(&[reply(id,&received(&[],false)),hint(91,99,2)]).await;next_reply(&mut peer,91,false).await;assert_eq!(cursor(&observed,&server_line),(0,2,2));assert_eq!(super::count(&observed),0);done.send(()).unwrap();finish_account(&mut peer).await;}).await});
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(finished).await.unwrap();assert!(manager.im_messages(&line,16).unwrap().is_empty());assert!(temp.database.get_recent_app_events(Some(&line),16).unwrap().iter().all(|e|e.event_type!="im.received"));assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();
}).await;}
#[tokio::test]
async fn im_sync_account_unsupported_gap_record_keeps_cursor_and_sql_atomic_and_does_not_replay_read(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(config(&cert.root,port,100),100).await.unwrap().account;let line=account.line_id.clone();let observed=temp.database.clone();let server_line=line.clone();let(done,finished)=tokio::sync::oneshot::channel();
    let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;login_host(&mut peer).await;refresh(&mut peer,0,2,1).await;let packet=group(&mut peer,n::im_data::RECV_METHOD).await;let(id,start,count)=receive_span(&packet);assert_eq!((start,count),(1,2));peer.send(&[reply(id,&received(&[1,2],true)),hint(91,99,1)]).await;next_reply(&mut peer,91,false).await;assert_eq!(cursor(&observed,&server_line),(0,0,2));assert_eq!(super::count(&observed),0);done.send(()).unwrap();finish_account(&mut peer).await;}).await});
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(finished).await.unwrap();let view=manager.get(&line,100).await.unwrap();assert_eq!(view.phase,"hosted");assert_eq!(view.last_error,Some("app_account_im_type_unsupported"));assert!(manager.im_messages(&line,16).unwrap().is_empty());assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();
}).await;}
#[tokio::test]
async fn im_sync_account_read_timeout_is_one_attempt_keeps_sdk_healthy_and_ignores_late_reply_before_logout(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(config(&cert.root,port,100),100).await.unwrap().account;let line=account.line_id.clone();let(go,wait)=tokio::sync::oneshot::channel();let(ready,seen)=tokio::sync::oneshot::channel();
    let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;login_host(&mut peer).await;let packet=group(&mut peer,n::im_status::REFRESH_METHOD).await;let id=decode_request(&packet[1..]).unwrap().call_id;ready.send(()).unwrap();wait.await.unwrap();peer.send(&[reply(id,&[0])]).await;finish_account(&mut peer).await;}).await});
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(seen).await.unwrap();bounded(async{loop{let view=manager.get(&line,100).await.unwrap();if view.last_error==Some("app_account_im_sync_read_timeout"){assert_eq!(view.phase,"hosted");break;}tokio::time::sleep(Duration::from_millis(5)).await;}}).await;go.send(()).unwrap();assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();assert!(manager.im_messages(&line,16).unwrap().is_empty());
}).await;}
#[tokio::test]
async fn im_sync_account_stop_retires_fully_submitted_read_before_late_result_and_retains_all_original_joins(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(config(&cert.root,port,100),100).await.unwrap().account;let line=account.line_id.clone();let(ready,seen)=tokio::sync::oneshot::channel();
    let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;login_host(&mut peer).await;let packet=group(&mut peer,n::im_status::REFRESH_METHOD).await;let id=decode_request(&packet[1..]).unwrap().call_id;ready.send(()).unwrap();let(_,flag)=hosting_call(&mut peer).await;assert_eq!(flag,b"3");peer.send(&[reply(id,&[0])]).await;loop{let p=peer.next().await.unwrap();let r=decode_request(&p[1..]).unwrap();if r.method==n::rpc_logout::LOGOUT_SESSION_METHOD.as_bytes(){peer.send(&[reply(r.call_id,&[0,1,0,0,0,0])]).await;break;}swap(&mut peer,&p).await;}while peer.next().await.is_some(){};}).await});
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(seen).await.unwrap();let stopped=bounded(manager.stop(&line,account.revision,100)).await.unwrap();assert!(!stopped.io_cleanup_required);bounded(serving).await.unwrap();assert_eq!(super::count(&temp.database),0);assert!(!temp.database.with_conn(|c|n::account_runs::ownership_pending(c,&line)).unwrap());
}).await;}
#[tokio::test]
async fn im_sync_account_explicit_restart_rechecks_status_and_retains_durable_cursor_and_deleted_tombstone(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(config(&cert.root,port,3000),100).await.unwrap().account;let line=account.line_id.clone();let(ready1,done1)=tokio::sync::oneshot::channel();let(ready2,done2)=tokio::sync::oneshot::channel();
    let serving=tokio::spawn(async move{bounded(async move{
        // Two accepts share the same bound original listener. Duplicating its
        // OS handle does not rebind a port or create a replacement client scope.
        let original_listener=listener.into_std().unwrap();
        let second_listener=TcpListener::from_std(original_listener.try_clone().unwrap()).unwrap();
        let listener=TcpListener::from_std(original_listener).unwrap();
        let mut peer=CommonPeer::open(listener,server.clone()).await;login_host(&mut peer).await;refresh(&mut peer,0,2,1).await;let p=group(&mut peer,n::im_data::RECV_METHOD).await;let(id,start,count)=receive_span(&p);assert_eq!((start,count),(1,2));peer.send(&[reply(id,&received(&[1,2],false)),hint(91,99,2)]).await;next_reply(&mut peer,91,true).await;ready1.send(()).unwrap();finish_account(&mut peer).await;
        let mut peer=CommonPeer::open(second_listener,server).await;login_host(&mut peer).await;refresh(&mut peer,0,3,2).await;let p=group(&mut peer,n::im_data::RECV_METHOD).await;let(id,start,count)=receive_span(&p);assert_eq!((start,count),(3,1),"new remote peer-read cannot reset durable local consumption");peer.send(&[reply(id,&received(&[3],false)),hint(91,99,3)]).await;next_reply(&mut peer,91,true).await;peer.send(&[message(92,1,true)]).await;next_reply(&mut peer,92,true).await;ready2.send(()).unwrap();finish_account(&mut peer).await;
    }).await});
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(done1).await.unwrap();let rows=manager.im_messages(&line,16).unwrap();let deleted=rows.iter().find(|r|r.message_index=="1").unwrap().id;assert!(manager.delete_im_message(&line,deleted).unwrap());assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);assert_eq!(cursor(&temp.database,&line),(0,2,2));bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(done2).await.unwrap();let rows=manager.im_messages(&line,16).unwrap();assert_eq!(rows.iter().map(|r|r.message_index.as_str()).collect::<Vec<_>>(),["3","2"]);assert_eq!(super::count(&temp.database),3);assert_eq!(temp.database.get_recent_app_events(Some(&line),16).unwrap().iter().filter(|e|e.event_type=="im.received").count(),3);assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();assert_eq!(cursor(&temp.database,&line),(0,3,3));
}).await;}
